'use strict';
const KEY='zaiziwei-procurement-v1';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const clone=o=>JSON.parse(JSON.stringify(o));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number.isFinite(n)?'NT$ '+n.toLocaleString('zh-TW',{maximumFractionDigits:2}):'—';
const num=v=>v===''||v==null?null:Number(v);
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()).replace(/\//g,'-');
const safeUrl=u=>{try{const x=new URL(u);return ['https:','http:'].includes(x.protocol)?x.href:''}catch{return ''}};
let state=clone(SEED),draft=null,editingSupplier='',currentView='products',toastTimer;
function validData(s){return s&&s.schema===1&&Array.isArray(s.products)&&s.products.length<=5000&&s.products.every(p=>Number.isInteger(p.id)&&typeof p.name==='string'&&Number.isInteger(p.qty)&&p.qty>0&&Array.isArray(p.quotes)&&p.quotes.every(q=>typeof q.supplier==='string'&&typeof q.id==='string'&&['price','shipping','moq'].every(k=>q[k]==null||(typeof q[k]==='number'&&Number.isFinite(q[k])&&q[k]>=0)))&&(p.sale==null||(typeof p.sale==='number'&&Number.isFinite(p.sale)&&p.sale>=0)))&&new Set(s.products.map(p=>p.id)).size===s.products.length&&s.contacts&&typeof s.contacts==='object'&&!Array.isArray(s.contacts)}
try{const stored=localStorage.getItem(KEY);if(stored){const saved=JSON.parse(stored);if(!validData(saved))throw Error('備份結構不符');state=saved;$('#save-status').textContent='已載入本機資料'}}catch(e){$('#notice').textContent='無法讀取本機資料，現在顯示原始清單。若已有備份請匯入；請勿在未確認前覆蓋重要資料。'}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function persist(){try{state.updatedAt=new Date().toISOString();localStorage.setItem(KEY,JSON.stringify(state));$('#save-status').textContent='已儲存 '+new Date().toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit'});return true}catch(e){toast('無法寫入瀏覽器，請立即匯出備份以保留資料');$('#save-status').textContent='儲存失敗，請備份';return false}}
function quoteCalc(p,q){const qty=p.qty,issues=[];if(q.price==null)issues.push('尚未報價');if(!['含稅','未稅5%','零稅／免稅'].includes(q.tax))issues.push('稅別待確認');if(q.validUntil&&q.validUntil<today())issues.push('報價已過期');if(q.moq&&qty<q.moq)issues.push('未達最低訂購量');if(q.stage!=='已報價'&&q.stage!=='已選定')issues.push('非正式報價');const unit=q.price==null?null:q.price*(q.tax==='未稅5%'?1.05:1)+(q.shipping||0)/qty;return {unit,total:unit==null?null:unit*qty,issues,eligible:issues.length===0}}
function best(p){return p.quotes.map(q=>({q,...quoteCalc(p,q)})).filter(x=>x.eligible).sort((a,b)=>a.unit-b.unit)[0]}
function verified(p){return new Set(p.quotes.filter(q=>q.status==='已見同規格販售').map(q=>q.supplierGroup||q.supplier.trim())).size}
function allSuppliers(){const m=new Map();for(const p of state.products)for(const q of p.quotes){const n=q.supplier.trim();if(!n)continue;if(!m.has(n))m.set(n,{name:n,products:new Set(),verified:0,types:new Set(),url:''});const s=m.get(n);s.products.add(p.id);s.types.add(q.type);if(q.status==='已見同規格販售')s.verified++;if(!s.url&&safeUrl(q.url))s.url=q.url}return [...m.values()].sort((a,b)=>b.products.size-a.products.size||a.name.localeCompare(b.name,'zh-TW'))}
function render(){renderMetrics();renderCategories();renderProducts();renderSuppliers();renderRfqSelect();$('#data-date').textContent='資料查核：'+(state.checkedAt||'尚未匯入')+' · 本機儲存，不上傳'}
function renderMetrics(){const ps=state.products;const cov=ps.filter(p=>verified(p)>=3).length;const quotes=ps.filter(p=>p.quotes.some(q=>q.price!=null)).length;const chosen=ps.map(p=>{const q=p.quotes.find(q=>q.id===p.selected);return q?quoteCalc(p,q):null}).filter(c=>c&&c.eligible);const total=chosen.reduce((a,c)=>a+c.total,0);$('#metrics').innerHTML=[['管理商品',ps.length+' 項',ps.reduce((a,p)=>a+p.qty,0).toLocaleString()+' 個訂購單位'],['三家販售已查證',cov+' / '+ps.length,'其餘 '+(ps.length-cov)+' 項仍有查證缺口'],['已輸入報價',quotes+' 項','正式報價請確認稅別與有效日期'],['選定採購金額',money(total),chosen.length+' 項有效選定報價，不含未報價商品']].map(x=>`<div class="metric"><div class="label">${x[0]}</div><strong>${x[1]}</strong><small>${x[2]}</small></div>`).join('')}
function renderCategories(){const old=$('#category').value;$('#category').innerHTML='<option value="">所有分類</option>'+[...new Set(state.products.map(p=>p.category))].map(c=>`<option>${esc(c)}</option>`).join('');$('#category').value=old}
function filtered(){const q=$('#search').value.toLowerCase().trim(),cat=$('#category').value,f=$('#filter').value;return state.products.filter(p=>(!q||(p.name+' '+p.english+' '+p.quotes.map(x=>x.supplier).join(' ')).toLowerCase().includes(q))&&(!cat||p.category===cat)&&(!f||(f==='gap'&&verified(p)<3)||(f==='quoted'&&p.quotes.some(q=>q.price!=null))||(f==='unquoted'&&!p.quotes.some(q=>q.price!=null))||(f==='selected'&&p.selected)||(f==='expired'&&p.quotes.some(q=>q.price!=null&&q.validUntil&&q.validUntil<today()))))}
function renderProducts(){const ps=filtered();$('#result-count').textContent=`顯示 ${ps.length} / ${state.products.length} 項`;$('#empty').hidden=ps.length!==0;$('#product-body').innerHTML=ps.map(p=>{const v=verified(p),b=best(p);return `<tr><td><button class="product-name" data-product="${p.id}">${esc(p.name)}<small>#${String(p.id).padStart(3,'0')} · ${esc(p.unit||'依品名包裝單位')}</small></button></td><td>${p.qty.toLocaleString()}<div class="muted small">${p.caseSize?Math.ceil(p.qty/p.caseSize)+' 箱（進位參考）':'箱入數待確認'}</div></td><td><span class="chip ${v>=3?'':'warn'}">${v} / 3 家</span><div class="muted small">${p.quotes.length} 筆供應商紀錄</div></td><td>${p.estimate?money(p.estimate):'—'}<div class="muted small">歷史初估・非報價</div></td><td><span class="money">${b?money(b.unit):'待詢價'}</span>${b?`<div class="muted small">${esc(b.q.supplier)}</div>`:''}</td><td>${p.sale==null?'未設定':money(p.sale)}</td><td><button class="button" data-product="${p.id}">管理 ↗</button></td></tr>`}).join('')}
function renderSuppliers(){const needle=$('#supplier-search').value.trim().toLowerCase();$('#supplier-grid').innerHTML=allSuppliers().filter(s=>s.name.toLowerCase().includes(needle)).map(s=>{const c=state.contacts[s.name]||{};return `<article class="supplier-card"><span class="chip">${esc([...s.types].join(' / '))}</span><h3>${esc(s.name)}</h3><p>${s.products.size} 項關聯商品 <span class="muted small">· ${s.verified} 筆同規格販售證據</span></p><div class="contact-lines">${esc(c.contact||'聯絡人待補')}<br>${esc(c.phone||'電話待補')}<br>${esc(c.email||'Email待補')}</div>${s.url?`<p><a href="${esc(safeUrl(s.url))}" target="_blank" rel="noopener noreferrer">查看販售資料 ↗</a></p>`:''}<button class="button" data-supplier="${esc(s.name)}">管理聯絡資料</button> <button class="button" data-rfq="${esc(s.name)}">製作詢價單</button></article>`}).join('')}
const viewInfo={products:['商品與比價','從供貨查證到正式報價，每一項都有依據。'],suppliers:['供應商名錄','集中管理合作窗口，保留每項商品的供貨證據。'],rfq:['製作詢價單','依供應商彙整需求，確認後複製或下載。']};
function setView(v){currentView=v;for(const x of Object.keys(viewInfo))$('#'+x+'-view').hidden=x!==v;$$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#view-title').textContent=viewInfo[v][0];$('#view-desc').textContent=viewInfo[v][1];if(v==='rfq')renderRfq()}
function syncFields(){if(!draft)return;draft.name=$('#p-name').value.trim();draft.english=$('#p-english').value.trim();draft.category=$('#p-category').value.trim()||'其他';draft.unit=$('#p-unit').value.trim();draft.qty=Number($('#p-qty').value);draft.caseSize=num($('#p-case').value);draft.sale=num($('#p-sale').value);draft.selected=$('#p-selected').value||null;draft.note=$('#p-note').value}
function fillFields(){$('#p-name').value=draft.name;$('#p-english').value=draft.english||'';$('#p-category').value=draft.category;$('#p-unit').value=draft.unit||'';$('#p-qty').value=draft.qty;$('#p-case').value=draft.caseSize??'';$('#p-sale').value=draft.sale??'';$('#p-note').value=draft.note||'';fillSelect();renderMargin()}
function fillSelect(){const old=draft.selected;$('#p-selected').innerHTML='<option value="">尚未選定</option>'+draft.quotes.map(q=>`<option value="${esc(q.id)}">${esc(q.supplier||'未命名供應商')}</option>`).join('');$('#p-selected').value=old||''}
function openProduct(id){draft=clone(state.products.find(p=>p.id===id));$('#product-code').textContent='PRODUCT / '+String(draft.id).padStart(3,'0');$('#product-title').textContent=draft.name;fillFields();renderQuotes();switchTab('compare');$('#product-dialog').showModal()}
function switchTab(t){$$('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));$('#compare-tab').hidden=t!=='compare';$('#details-tab').hidden=t!=='details'}
const options=(values,current)=>values.map(x=>`<option${x===current?' selected':''}>${esc(x)}</option>`).join('');
function renderQuotes(){const v=verified(draft);$('#product-summary').innerHTML=`<span>訂購 <b>${draft.qty.toLocaleString()}</b> 個單位</span><span>同規格販售查證 <b>${v} / 3</b> 家</span><span>歷史參考 ${money(draft.estimate)}</span>`;$('#quote-list').innerHTML=draft.quotes.length?draft.quotes.map(q=>{const c=quoteCalc(draft,q),u=safeUrl(q.url);return `<article class="quote-card" data-qid="${esc(q.id)}"><div class="quote-top"><input data-q="supplier" value="${esc(q.supplier)}" placeholder="供應商名稱" aria-label="供應商名稱" required><select data-q="type" aria-label="供應商類型">${options(['批發商','品牌','零售通路','經銷商','其他'],q.type)}</select><button class="icon-button danger" type="button" data-remove="${esc(q.id)}" aria-label="移除此供應商紀錄">×</button></div><div class="quote-evidence"><span class="chip ${q.status==='已見同規格販售'?'':'warn'}">${esc(q.status)}</span> 查核 ${esc(q.checkedAt||'未查核')}<br>${esc(q.note||'尚無公開販售證據')}</div><div class="quote-url"><input data-q="url" value="${esc(q.url)}" placeholder="商品／批發來源網址" aria-label="供應商來源網址">${u?`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">查看來源 ↗</a>`:''}</div><div class="quote-fields"><label>單位報價（TWD）<input data-q="price" type="number" min="0" step="0.01" value="${q.price??''}" placeholder="待報價"></label><label>稅別<select data-q="tax">${options(['待確認','含稅','未稅5%','零稅／免稅'],q.tax)}</select></label><label>本項分攤運費<input data-q="shipping" type="number" min="0" step="0.01" value="${q.shipping??''}" placeholder="0"></label><label>最低訂購量（同單位）<input data-q="moq" type="number" min="0" step="1" value="${q.moq??''}" placeholder="待確認"></label><label>詢價進度<select data-q="stage">${options(['待詢價','已詢價','已報價','無法供貨','已選定'],q.stage)}</select></label><label>報價日期<input data-q="quotedAt" type="date" value="${esc(q.quotedAt||'')}"></label><label>報價有效至<input data-q="validUntil" type="date" value="${esc(q.validUntil||'')}"></label><label>交期<input data-q="leadTime" value="${esc(q.leadTime||'')}" placeholder="例如 7工作天"></label><label class="wide">出貨效期／批發條件<input data-q="shelfLife" value="${esc(q.shelfLife||'')}" placeholder="待供應商確認"></label></div><textarea class="quote-note" data-q="buyerNote" placeholder="詢價紀錄、聯絡窗口或未含費用…" aria-label="詢價備註">${esc(q.buyerNote||'')}</textarea><div class="quote-total"><label><input type="radio" name="quote-choice" data-choose="${esc(q.id)}" ${draft.selected===q.id?'checked':''}>選為採購來源</label><span class="calc-text">${quoteResult(c)}</span></div></article>`}).join(''):'<div class="coverage-empty">尚無供應商紀錄。新增供應商後，可填入來源與詢價結果。</div>';renderMargin()}
function quoteResult(c){return c.unit==null?'尚未輸入正式報價':`含稅到貨單價 <b>${money(c.unit)}</b> · 本項 ${money(c.total)}${c.issues.length?' <span class="danger">（'+c.issues.join('、')+'）</span>':''}`}
function renderMargin(){const q=draft.quotes.find(q=>q.id===draft.selected),c=q?quoteCalc(draft,q):null;$('#margin-preview').innerHTML=`<span>對客金額 <b>${draft.sale==null?'未設定':money(draft.sale*draft.qty)}</b></span><span>選定採購成本 <b>${c&&c.unit!=null?money(c.total):'未選定有效報價'}</b></span><span>商品差額 <b>${c&&c.eligible&&draft.sale!=null?money(draft.sale*draft.qty-c.total):'待完成報價'}</b></span>`}
function renderRfqSelect(){const old=$('#rfq-supplier').value;$('#rfq-supplier').innerHTML='<option value="">請選擇供應商</option>'+allSuppliers().map(s=>`<option>${esc(s.name)}</option>`).join('');$('#rfq-supplier').value=old;renderRfq()}
function renderRfq(){const s=$('#rfq-supplier').value;if(!s){$('#rfq-text').value='請先選擇供應商。';return}const lines=[`${s} 您好：`,'','我們是齋滋味，擬採購以下台灣食品，請協助確認供貨及批發報價。','用途：台灣採購後出口美國。以下品項部分僅為供貨候選，請逐項確認，不接受未經同意的規格替換。','','請提供：含／未稅單價、每箱入數、最低訂購量、庫存、交期、出貨效期、運費、報價有效期限及付款條件。',''];if($('#rfq-date').value)lines.push('希望回覆日期：'+$('#rfq-date').value,'');state.products.filter(p=>p.quotes.some(q=>q.supplier.trim()===s)).forEach((p,i)=>lines.push(`${i+1}. ${p.name}\n   數量：${p.qty} 個訂購單位；${p.unit||'依品名所列包裝'}${p.caseSize?'；每箱'+p.caseSize+'單位（請確認）':''}`));if($('#rfq-note').value)lines.push('','其他要求：',$('#rfq-note').value);lines.push('','煩請另確認可否提供原廠成分、營養標示及相關出口所需資料。','謝謝。');$('#rfq-text').value=lines.join('\n')}
function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function csvCell(v){const s=String(v??'');return '"'+(/^[=+@\-\t\r]/.test(s)?"'"+s:s).replace(/"/g,'""')+'"'}
function exportCsv(){const rows=[['品項編號','中文品名','訂購單位','需求數量','供應商','供應商類型','供貨查證','來源網址','查核日期','詢價狀態','單位報價TWD','稅別','本項分攤運費','MOQ','有效期限','含稅到貨單價','商品採購總額','可比較','採購選定','對客單價TWD','參考估價非報價','供貨證據備註','詢價紀錄']];for(const p of filtered())for(const q of p.quotes.length?p.quotes:[null]){const c=q?quoteCalc(p,q):null;rows.push([p.id,p.name,p.unit,p.qty,q?.supplier,q?.type,q?.status,q?.url,q?.checkedAt,q?.stage,q?.price,q?.tax,q?.shipping,q?.moq,q?.validUntil,c?.unit,c?.total,c?.eligible?'是':c?.issues.join('；'),q&&p.selected===q.id?'是':'',p.sale,p.estimate,q?.note,q?.buyerNote])}download('齋滋味詢價明細-'+today()+'.csv','\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('已匯出目前商品範圍的詢價明細')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view)setView(b.dataset.view);if(b.dataset.product)openProduct(Number(b.dataset.product));if(b.dataset.close)$('#'+b.dataset.close).close();if(b.dataset.tab){syncFields();switchTab(b.dataset.tab);if(b.dataset.tab==='compare')renderQuotes()}if(b.dataset.remove){if(!confirm('移除此商品的這筆供應商與報價紀錄？'))return;draft.quotes=draft.quotes.filter(q=>q.id!==b.dataset.remove);if(draft.selected===b.dataset.remove)draft.selected=null;fillSelect();renderQuotes()}if(b.dataset.supplier){editingSupplier=b.dataset.supplier;$('#supplier-title').textContent=editingSupplier;const c=state.contacts[editingSupplier]||{};for(const k of ['contact','phone','email','note'])$('#s-'+k).value=c[k]||'';$('#supplier-dialog').showModal()}if(b.dataset.rfq){setView('rfq');$('#rfq-supplier').value=b.dataset.rfq;renderRfq()}});
$('#quote-list').addEventListener('input',e=>{const card=e.target.closest('[data-qid]');if(!card)return;const q=draft.quotes.find(q=>q.id===card.dataset.qid),k=e.target.dataset.q;if(k){if(k==='supplier')delete q.supplierGroup;q[k]=['price','shipping','moq'].includes(k)?num(e.target.value):e.target.value;card.querySelector('.calc-text').innerHTML=quoteResult(quoteCalc(draft,q));if(k==='supplier')fillSelect();renderMargin()}if(e.target.dataset.choose){draft.selected=e.target.dataset.choose;fillSelect();renderMargin()}});
$('#details-tab').addEventListener('input',()=>{syncFields();renderMargin()});
$('#add-quote').onclick=()=>{syncFields();draft.quotes.push({id:'q-'+crypto.randomUUID(),supplier:'',url:'',type:'批發商',status:'待詢價',checkedAt:'',note:'使用者新增，供貨待確認',price:null,tax:'待確認',shipping:null,moq:null,stage:'待詢價'});fillSelect();renderQuotes()};
$('#product-form').onsubmit=e=>{e.preventDefault();syncFields();if(!draft.name||!Number.isInteger(draft.qty)||draft.qty<=0){toast('請填入品名與正整數數量');return}if(draft.quotes.some(q=>!q.supplier.trim())){switchTab('compare');toast('請填入供應商名稱或移除空白紀錄');return}const i=state.products.findIndex(p=>p.id===draft.id);if(i>=0)state.products[i]=draft;else state.products.push(draft);const ok=persist();$('#product-dialog').close();render();if(ok)toast('商品與報價已儲存')};
$('#supplier-form').onsubmit=e=>{e.preventDefault();if(['__proto__','constructor','prototype'].includes(editingSupplier))return toast('請使用有效的供應商名稱');state.contacts[editingSupplier]=Object.fromEntries(['contact','phone','email','note'].map(k=>[k,$('#s-'+k).value]));const ok=persist();$('#supplier-dialog').close();renderSuppliers();if(ok)toast('聯絡資料已儲存')};
$('#add-product').onclick=()=>{draft={id:Math.max(...state.products.map(p=>p.id),0)+1,name:'',english:'',category:'其他',unit:'',qty:1,caseSize:null,sale:null,estimate:null,note:'',quotes:[],selected:null};$('#product-title').textContent='新增商品';$('#product-code').textContent='NEW PRODUCT';fillFields();renderQuotes();switchTab('details');$('#product-dialog').showModal()};
for(const id of ['search','category','filter'])$('#'+id).addEventListener('input',renderProducts);$('#supplier-search').addEventListener('input',renderSuppliers);for(const id of ['rfq-supplier','rfq-date','rfq-note'])$('#'+id).addEventListener('input',renderRfq);
$('#rfq-copy').onclick=async()=>{if(!$('#rfq-supplier').value)return toast('請先選擇供應商');try{await navigator.clipboard.writeText($('#rfq-text').value);toast('已複製詢價內容')}catch{$('#rfq-text').select();toast('請按 Ctrl+C 複製選取文字')}};
$('#rfq-download').onclick=()=>{if(!$('#rfq-supplier').value)return toast('請先選擇供應商');download('齋滋味詢價單-'+today()+'.txt',$('#rfq-text').value,'text/plain;charset=utf-8')};
$('#export').onclick=exportCsv;
$('#backup').onclick=()=>{download('齋滋味採購備份-'+today()+'.json',JSON.stringify(state,null,2),'application/json');toast('完整備份已匯出，請妥善保存')};
$('#restore').onclick=()=>$('#restore-file').click();$('#import-main').onclick=()=>$('#restore-file').click();$('#restore-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error('檔案過大');const s=JSON.parse(await file.text());if(!validData(s))throw Error('不是有效的採購工具備份');if(!confirm(`匯入將取代目前資料（${s.products.length}項）。確定已備份目前資料？`))return;state=s;const ok=persist();render();if(ok)toast('備份匯入成功')}catch(err){toast('匯入失敗：'+err.message)}finally{e.target.value=''}};
render();
